"""Tests for MocapAnimationService: cleaning up the face curves, writing the shape key action, the drivers,
the NLA layers, baking and the sound strip."""

import math
import struct
import sys
import wave
import bpy
import numpy as np
import pytest

from .. import dynamic_import, FaceService, HumanService

MocapAnimationService = dynamic_import("mpfb.services.mocapanimationservice", "MocapAnimationService")
_MODULE = sys.modules[MocapAnimationService.__module__]

_NAMES = ["_neutral", "eyeBlinkLeft", "eyeBlinkRight", "jawOpen"]


def _write_face_source(path, frames=150, fps=30.0, start=1.0, gaps=()):
    times = start + np.arange(frames) / fps
    blink = np.where((times > 2.0) & (times < 2.15), 1.0, 0.05)
    values = np.stack([np.zeros(frames), blink, blink, 0.4 + 0.3 * np.sin(np.pi * times)], axis=1)
    for begin, end in gaps:
        values[begin:end] = np.nan
    np.savez(path, times_ms=np.round(times * 1000).astype(np.int64), blendshapes=values.astype(np.float32),
             blendshape_names=np.array(_NAMES), pose=np.zeros((frames, 33, 5), dtype=np.float32))
    return str(path)


def _mesh_with_shape_keys(name, keys):
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata([(0, 0, 0), (1, 0, 0), (0, 1, 0)], [], [(0, 1, 2)])
    obj = bpy.data.objects.new(name, mesh)
    bpy.context.scene.collection.objects.link(obj)
    obj.shape_key_add(name="Basis", from_mix=False)
    for key in keys:
        obj.shape_key_add(name=key, from_mix=False)
    return obj


def _remove(*objects):
    for obj in objects:
        mesh = obj.data
        bpy.data.objects.remove(obj, do_unlink=True)
        bpy.data.meshes.remove(mesh)


def test_service_is_not_instanced():
    with pytest.raises(RuntimeError):
        MocapAnimationService()


def test_neutral_is_dropped(tmp_path):
    _times, names, values = MocapAnimationService.load_face_source(_write_face_source(tmp_path / "face.npz"))
    assert names == ["eyeBlinkLeft", "eyeBlinkRight", "jawOpen"]
    assert values.shape == (150, 3)


def test_mirror_name():
    assert MocapAnimationService.mirror_name("eyeBlinkLeft") == "eyeBlinkRight"
    assert MocapAnimationService.mirror_name("mouthRight") == "mouthLeft"
    assert MocapAnimationService.mirror_name("jawOpen") == "jawOpen"


def test_short_gap_is_interpolated_and_long_gap_fades():
    times = np.arange(100) / 30.0
    values = np.full((100, 1), 0.6)
    values[10:15] = np.nan    # 0.2 s
    values[50:80] = np.nan    # 1 s
    filled = MocapAnimationService.fill_gaps(times, values)
    assert filled[12, 0] == pytest.approx(0.6)
    assert filled[50, 0] < 0.6
    assert filled[65, 0] == 0.0
    assert not np.isnan(filled).any()


def test_no_detection_at_all_gives_zeros():
    values = np.full((10, 2), np.nan)
    assert (MocapAnimationService.fill_gaps(np.arange(10) / 30.0, values) == 0).all()


def test_smoothing_reduces_jitter_but_keeps_timing():
    times = np.arange(150) / 30.0
    clean = 0.4 + 0.3 * np.sin(np.pi * times)
    noisy = (clean + np.random.default_rng(1).normal(0, 0.04, len(times)))[:, None]
    smooth = MocapAnimationService.smooth(times, noisy, 0.5)
    assert np.std(np.diff(smooth[:, 0])) < 0.6 * np.std(np.diff(noisy[:, 0]))
    assert abs(int(np.argmax(smooth[:60, 0])) - int(np.argmax(clean[:60]))) <= 2
    assert (MocapAnimationService.smooth(times, noisy, 0.0) == noisy).all()


def test_neutral_face_is_subtracted():
    result = MocapAnimationService.remove_neutral(np.array([[0.2, 0.6, 1.0]]), np.array([0.2, 0.2, 0.2]))
    assert result[0].tolist() == pytest.approx([0.0, 0.5, 1.0])


def test_curves_are_resampled_to_scene_fps(tmp_path):
    path = _write_face_source(tmp_path / "face.npz", frames=150, fps=30.0)
    curves = MocapAnimationService.prepare_face_curves(path, {"smoothing": 0.0, "mirror": True}, 24.0)
    assert curves["frames"] == 120
    assert curves["start"] == pytest.approx(1.0)
    assert curves["names"] == ["eyeBlinkRight", "eyeBlinkLeft", "jawOpen"]
    assert curves["values"].min() >= 0.0 and curves["values"].max() <= 1.0


def test_source_without_face_is_rejected(tmp_path):
    path = _write_face_source(tmp_path / "face.npz", frames=20, gaps=[(0, 20)])
    with pytest.raises(ValueError):
        MocapAnimationService.prepare_face_curves(path, {}, 24.0)


def test_action_is_written_on_the_shape_keys():
    obj = _mesh_with_shape_keys("mocap_action_test", ["jawOpen", "eyeBlinkLeft"])
    key = obj.data.shape_keys
    values = np.array([[0.0, 1.0], [0.5, 0.0], [1.0, 0.25]])
    action = MocapAnimationService.write_shape_key_action(key, "MPFB_Face_test", 10, ["jawOpen", "eyeBlinkLeft", "tongueOut"],
                                                          np.column_stack([values, np.zeros(3)]))
    try:
        assert key.animation_data.action == action
        assert action.use_fake_user
        scene = bpy.context.scene
        for row, frame in enumerate((10, 11, 12)):
            scene.frame_set(frame)
            assert key.key_blocks["jawOpen"].value == pytest.approx(values[row, 0], abs=1e-4)
            assert key.key_blocks["eyeBlinkLeft"].value == pytest.approx(values[row, 1], abs=1e-4)
    finally:
        _remove(obj)
        bpy.data.actions.remove(action)


def test_fitted_meshes_get_drivers(monkeypatch):
    basemesh = _mesh_with_shape_keys("mocap_driver_base", ["jawOpen", "eyeBlinkLeft"])
    child = _mesh_with_shape_keys("mocap_driver_child", ["jawOpen"])
    monkeypatch.setattr(MocapAnimationService, "fitted_children", staticmethod(lambda _basemesh: [child]))
    try:
        assert MocapAnimationService.drive_children(basemesh, ["jawOpen", "eyeBlinkLeft"]) == 1
        drivers = child.data.shape_keys.animation_data.drivers
        fcurve = drivers.find('key_blocks["jawOpen"].value')
        target = fcurve.driver.variables[0].targets[0]
        assert target.id == basemesh.data.shape_keys
        assert target.data_path == 'key_blocks["jawOpen"].value'
        # A second run does not add the drivers again
        assert MocapAnimationService.drive_children(basemesh, ["jawOpen"]) == 1
        assert len(drivers) == 1
    finally:
        _remove(child, basemesh)


def test_face_animation_on_a_character(tmp_path):
    if not FaceService.is_faceunits01_installed():
        pytest.skip("faceunits01 is not installed")
    basemesh = HumanService.create_human()
    scene = bpy.context.scene
    scene.frame_current = 5
    path = _write_face_source(tmp_path / "video1_clip_landmarks.npz")
    result = MocapAnimationService.create_face_animation(basemesh, path, {"include_children": False}, scene, "clip.mp4")
    action = bpy.data.actions[result["action"]]
    try:
        assert result["action"].startswith("MPFB_Face_clip")
        assert result["animated"] == 3
        assert result["frame_start"] == 5
        assert scene.frame_end >= result["frame_end"]
        animation_data = basemesh.data.shape_keys.animation_data
        assert animation_data.action is None
        track = animation_data.nla_tracks[_MODULE.FACE_TRACK]
        assert track.strips[0].action == action
        assert track.strips[0].frame_start == 5
    finally:
        bpy.data.actions.remove(action)


def test_face_animation_leaves_speech_to_the_lipsync(tmp_path):
    if not FaceService.is_faceunits01_installed():
        pytest.skip("faceunits01 is not installed")
    basemesh = HumanService.create_human()
    path = _write_face_source(tmp_path / "video1_clip_landmarks.npz")
    result = MocapAnimationService.create_face_animation(basemesh, path, {"include_children": False, "skip_speech": True},
                                                         bpy.context.scene, "clip.mp4")
    action = bpy.data.actions[result["action"]]
    try:
        paths = [fcurve.data_path for fcurve in MocapAnimationService._action_fcurves(action)]
        assert 'key_blocks["eyeBlinkLeft"].value' in paths
        assert 'key_blocks["jawOpen"].value' not in paths
        assert result["skipped_speech"]
    finally:
        bpy.data.actions.remove(action)


def _layered_mesh():
    """A mesh with a face layer (jawOpen 0.5) and a lipsync layer (viseme_aa 1.0) on NLA tracks."""
    obj = _mesh_with_shape_keys("mocap_layers_test", ["jawOpen", "viseme_aa"])
    key = obj.data.shape_keys
    face = MocapAnimationService.write_shape_key_action(key, "MPFB_Face_test", 1, ["jawOpen"], np.full((10, 1), 0.5))
    MocapAnimationService.place_on_track(key, face, _MODULE.FACE_TRACK, 1, 10)
    lipsync = MocapAnimationService.write_shape_key_action(key, "MPFB_Lipsync_test", 3, ["viseme_aa"], np.ones((4, 1)))
    MocapAnimationService.place_on_track(key, lipsync, _MODULE.LIPSYNC_TRACK, 3, 6)
    return obj, [face, lipsync]


def test_layers_are_separate_nla_tracks():
    obj, actions = _layered_mesh()
    key = obj.data.shape_keys
    try:
        assert key.animation_data.action is None
        assert [track.name for track in MocapAnimationService.layer_tracks(obj)] == [_MODULE.FACE_TRACK, _MODULE.LIPSYNC_TRACK]
        bpy.context.scene.frame_set(4)
        assert key.key_blocks["jawOpen"].value == pytest.approx(0.5, abs=1e-4)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(1.0, abs=1e-4)
        # A new lipsync over the same frames replaces the old strip
        again = MocapAnimationService.write_shape_key_action(key, "MPFB_Lipsync_again", 4, ["viseme_aa"], np.ones((2, 1)))
        actions.append(again)
        MocapAnimationService.place_on_track(key, again, _MODULE.LIPSYNC_TRACK, 4, 5)
        assert [strip.action for strip in key.animation_data.nla_tracks[_MODULE.LIPSYNC_TRACK].strips] == [again]
    finally:
        _remove(obj)
        for action in actions:
            bpy.data.actions.remove(action)


def test_layers_bake_into_one_action():
    obj, actions = _layered_mesh()
    key = obj.data.shape_keys
    try:
        result = MocapAnimationService.bake_layers(obj)
        baked = bpy.data.actions[result["action"]]
        actions.append(baked)
        assert key.animation_data.action == baked
        assert all(track.mute for track in MocapAnimationService.layer_tracks(obj))
        assert (result["frame_start"], result["frame_end"]) == (1, 10)
        scene = bpy.context.scene
        scene.frame_set(4)
        assert key.key_blocks["jawOpen"].value == pytest.approx(0.5, abs=1e-4)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(1.0, abs=1e-4)
        scene.frame_set(8)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(0.0, abs=1e-4)
    finally:
        _remove(obj)
        for action in actions:
            bpy.data.actions.remove(action)


def test_sound_strip_is_placed_and_trimmed(tmp_path):
    path = str(tmp_path / "line.wav")
    with wave.open(path, "wb") as sound:
        sound.setnchannels(1)
        sound.setsampwidth(2)
        sound.setframerate(16000)
        sound.writeframes(b"".join(struct.pack("<h", int(8000 * math.sin(i / 10.0))) for i in range(16000 * 4)))
    scene = bpy.context.scene
    fps = scene.render.fps / scene.render.fps_base
    try:
        strip = MocapAnimationService.add_sound_strip(scene, path, "MPFB_Lipsync_line", 20, 1.0, int(2 * fps), fps)
    except RuntimeError as err:
        pytest.skip("No sound support in this blender: %s" % err)
    try:
        assert strip.frame_final_start == 20
        assert strip.frame_final_end == pytest.approx(20 + int(2 * fps), abs=1)
    finally:
        editor = scene.sequence_editor
        (editor.strips if hasattr(editor, "strips") else editor.sequences).remove(strip)


def test_livelink_csv_gives_face_curves(tmp_path):
    names = ["Timecode", "BlendShapeCount", "EyeBlinkLeft", "JawOpen", "TongueOut", "HeadYaw"]
    lines = [",".join(names)]
    for frame in range(60):
        lines.append("00:00:01:%02d.000,52,%.3f,0.5,0.2,0.1" % (frame, 1.0 if 20 <= frame < 26 else 0.0))
    path = tmp_path / "take.csv"
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    curves = MocapAnimationService.prepare_face_curves(str(path), {"smoothing": 0.0}, 30.0)
    assert curves["names"] == ["eyeBlinkLeft", "jawOpen", "tongueOut"]
    assert curves["frames"] == 30
    assert np.allclose(curves["values"][:, 1], 0.5)
    assert curves["values"][:, 0].max() == pytest.approx(1.0)
